def describe(x):
    if isinstance(x, bool):
        return "yes/no"
    elif isinstance(x, (int, float)):
        return "number"
    elif isinstance(x, str):
        return "text"
    return "other"

print(describe(True), describe(3), describe("a"), describe([1]))
Order matters: test the narrower class (bool) before the wider one (int).

