    def __init__(self, name, age):
        self.name = name
        self.age = age

rex = Dog("Rex")
TypeError: Dog.__init__() missing 1 required positional argument: 'age'. self is never counted by the caller.

class Dog:
    def __int__(self, name):
        self.name = name

rex = Dog("Rex")
TypeError: Dog() takes no arguments: __int__ is not __init__. Writing name = name without self. stores nothing on the object.

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

print(Account("Ann").balance, Account("Bo", 50).balance)   # 0 50
Defaults work in __init__ exactly as in any function.

