Each call starts from the state the previous call left behind.

class Counter:
    def __init__(self):
        self.count = 0

    def increment(self):
        self.count += 1

a = Counter()
b = Counter()
a.increment(); a.increment(); b.increment()
print(a.count, b.count)   # 2 1
The same method changes only the object before the dot.

class LunchCard:
    def __init__(self, balance):
        self.balance = balance

    def eat(self):
        if self.balance >= 3:
            self.balance -= 3
            return True
        return False

card = LunchCard(4)
print(card.eat(), card.eat(), card.balance)   # True False 1
The method checks before it changes, so the balance can never go negative.

class Account:
    def __init__(self, balance):
        self.balance = balance

    def can_pay(self, amount):
        return amount <= self.balance

    def pay(self, amount):
        if self.can_pay(amount):
            self.balance -= amount

a = Account(10)
a.pay(4); a.pay(9)
print(a.balance)   # 6
Inside a class, methods call each other as self.method(...).

class Account:
    def __init__(self, balance):
        self.balance = balance

    def can_pay(self, amount):
        return amount <= self.balance

    def pay(self, amount):
        if can_pay(amount):
            self.balance -= amount

Account(10).pay(4)
NameError: name 'can_pay' is not defined. Did you mean: 'self.can_pay'? Methods live on the object, not as plain names.

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other):
        return abs(self.x - other.x) + abs(self.y - other.y)

print(Point(1, 2).distance_to(Point(4, 6)))   # 7
self is one point and other is the second; read each one's attributes.

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def moved(self, dx, dy):
        return Point(self.x + dx, self.y + dy)

p = Point(1, 1)
q = p.moved(2, 0)
print(p.x, q.x)   # 1 3
moved returns a new Point and leaves p alone; a move method would change p and return None.

class Counter:
    def __init__(self):
        self.count = 0

def bump(c):
    c.count += 1

def replace(c):
    c = Counter()

x = Counter()
bump(x); replace(x)
print(x.count)   # 1
Changing the parameter's attributes changes the caller's object; reassigning the parameter does not.

