class Date:
    def __init__(self, year, month, day):
        self.year, self.month, self.day = year, month, day

    @classmethod
    def from_string(cls, text):
        y, m, d = text.split("-")
        return cls(int(y), int(m), int(d))

print(Date.from_string("2024-05-17").month)   # 5
cls(...) calls the constructor, so the class method builds and returns a new object.

class Book:
    def __init__(self, title, pages):
        self.title = title
        self.pages = pages

    def to_dict(self):
        return {"title": self.title, "pages": self.pages}

    @classmethod
    def from_dict(cls, d):
        return cls(d["title"], d["pages"])

copy = Book.from_dict(Book("Dune", 412).to_dict())
print(copy.title, copy.pages)   # Dune 412
to_dict and from_dict make a round trip, which is how objects are saved to and loaded from JSON.

