class Thermostat:
    def __init__(self):
        self._target = 20

    @property
    def target(self):
        return self._target

    @target.setter
    def target(self, value):
        if not 5 <= value <= 30:
            raise ValueError("out of range")
        self._target = value

t = Thermostat()
t.target = 25
print(t.target)   # 25
t.target = 99
t.target = 99 calls the setter, which raises ValueError: out of range.

class Student:
    def __init__(self, name):
        self.name = name          # goes through the setter

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if not value:
            raise ValueError("missing name")
        self._name = value

Student("")
ValueError: missing name. Assigning self.name in __init__ reuses the check, so creation and later changes obey one rule.

