print(Point(1, 2))   # Point(1, 2)
str falls back to __repr__, so one __repr__ is often enough.

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

print(Point(1, 2) == Point(1, 2))   # True (False without __eq__)
Without __eq__, == behaves like is; with it, == compares the data you choose.

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return self.x == other.x and self.y == other.y

print(Point(1, 2) == 5)   # False
Without the check, other.x would raise AttributeError; NotImplemented lets Python answer False.

class Card:
    def __init__(self, rank):
        self.rank = rank

    def __lt__(self, other):
        return self.rank < other.rank

    def __repr__(self):
        return f"Card({self.rank})"

print(sorted([Card(9), Card(2), Card(5)]))   # [Card(2), Card(5), Card(9)]
Without __lt__: TypeError: '<' not supported between instances of 'Card' and 'Card'.

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

print(Vector(1, 2) + Vector(3, 4))   # Vector(4, 6)
a + b calls a.__add__(b); return a new object and leave both operands unchanged.

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

Vector(1, 2) - Vector(3, 4)
TypeError: unsupported operand type(s) for -: 'Vector' and 'Vector'. Each operator needs its own method (__sub__ for -).

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __mul__(self, k):
        return Vector(self.x * k, self.y * k)

    __rmul__ = __mul__

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

print(Vector(1, 2) * 3, 3 * Vector(1, 2))   # Vector(3, 6) Vector(3, 6)
3 * v first asks int, which gives up; Python then tries v.__rmul__(3).

class Playlist:
    def __init__(self, songs):
        self.songs = list(songs)

    def __len__(self):
        return len(self.songs)

print(len(Playlist(["a", "b", "c"])))   # 3
len(obj) calls obj.__len__(); delegate to the list inside.

class Playlist:
    def __init__(self, songs):
        self.songs = list(songs)

    def __getitem__(self, i):
        return self.songs[i]

p = Playlist(["a", "b", "c"])
print(p[0], p[-1])   # a c
obj[i] calls obj.__getitem__(i); negative indexes and IndexError come free from the inner list.

class Playlist:
    def __init__(self, songs):
        self.songs = list(songs)

    def __contains__(self, song):
        return song.lower() in self.songs

print("ABBA" in Playlist(["abba", "queen"]))   # True
x in obj calls obj.__contains__(x), so you choose what counts as a match.

class Playlist:
    def __init__(self, songs):
        self.songs = list(songs)

    def __len__(self):
        return len(self.songs)

if not Playlist([]):
    print("nothing to play")   # nothing to play
With no __bool__, Python uses __len__: length 0 means False.

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

for n in Countdown(3):
    print(n)   # 3, 2, 1 on separate lines
for calls iter() once, then next() until StopIteration.

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

print(list(Countdown(3)), sum(Countdown(4)))   # [3, 2, 1] 10
list(), sum(), max() and unpacking all use the same iter/next protocol.

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

c = Countdown(2)
print(list(c), list(c))   # [2, 1] []
The state lives in the object, so the second loop finds it already exhausted.

class Countdown:
    def __init__(self, start):
        self.start = start

    def __iter__(self):
        n = self.start
        while n > 0:
            yield n
            n -= 1

c = Countdown(2)
print(list(c), list(c))   # [2, 1] [2, 1]
Each call of __iter__ starts a fresh generator, so every loop starts from the beginning.

class Timer:
    def __enter__(self):
        print("start")

    def __exit__(self, exc_type, exc, tb):
        print("stop")

with Timer():
    print("working")
Prints start, working, stop: __exit__ takes three arguments describing any error (all None here).

class Box:
    def __enter__(self):
        return ["tool"]

    def __exit__(self, exc_type, exc, tb):
        print("closed")

with Box() as items:
    print(items)   # ['tool'], then closed
Often __enter__ returns self; here it returns a list to show that as takes the return value.

class Timer:
    def __enter__(self):
        print("start")

    def __exit__(self, exc_type, exc, tb):
        print("stop, error was", exc_type)

try:
    with Timer():
        1 / 0
except ZeroDivisionError:
    print("handled")
Prints start, then stop, error was <class 'ZeroDivisionError'>, then handled: like finally, cleanup always happens and the error still propagates.
